import requests
import time

# NOTE: generated by Gemini 3
def count_wiki_category_with_subcats(category_name, is_simple=True):
    subdomain = "simple" if is_simple else "en"
    url = f"https://{subdomain}.wikipedia.org/w/api.php"
    
    headers = {
        "User-Agent": "RAG-Student-Project/1.0 (educational use;)"
    }
    
    visited_categories = set()
    all_articles = set()

    def fetch_category(cat_title):
        # Нормалізуємо назву (прибираємо "Category:" якщо передали з ним)
        cat_title = cat_title.replace("Category:", "")
        if cat_title in visited_categories:
            return
        visited_categories.add(cat_title)
        
        params = {
            "action": "query",
            "list": "categorymembers",
            "cmtitle": f"Category:{cat_title}",
            "cmlimit": "max",
            "format": "json"
        }
        
        continue_token = None
        while True:
            if continue_token:
                params["cmcontinue"] = continue_token
            else:
                params.pop("cmcontinue", None)
                
            try:
                response = requests.get(url, params=params, headers=headers, timeout=10)
                if response.status_code != 200 or not response.text.strip():
                    break
                data = response.json()
            except Exception:
                break
            
            members = data.get("query", {}).get("categorymembers", [])
            for m in members:
                if m["ns"] == 0:  # Стаття
                    all_articles.add(m["pageid"])
                elif m["ns"] == 14:  # Підкатегорія
                    sub_cat_title = m["title"].replace("Category:", "")
                    fetch_category(sub_cat_title)
            
            time.sleep(0.1) # Коротка пауза для ввічливості до API
            
            if "continue" in data:
                continue_token = data["continue"]["cmcontinue"]
            else:
                break

    print(f"Сканування категорії '{category_name}' на {subdomain}.wikipedia.org...")
    fetch_category(category_name)
    
    print(f"-> Унікальних статей у категорії та її підкатегоріях: {len(all_articles)}\n")
    return len(all_articles)

if __name__ == "__main__":
    count_wiki_category_with_subcats("Category:19th-century_American_novelists", is_simple=False)
    count_wiki_category_with_subcats("Category:20th-century_American_novelists", is_simple=False)
